// TestVideoItemPagesJointE2E — video-item-pages box 4.1, the Tier-1 joint
// behind the SPA's video-gate fix: a fixture serial library through the REAL
// scan (serial-scanner subprocess + real ffprobe over the pbWorld composed
// graph), asserting the stored document satisfies the descriptor contract the
// SPA player mounts (web PlaybackDescriptor). Zero Go changes is the change's
// D-4 posture — this test pins the production facts that make a web-only fix
// sufficient:
//
//   - vocabulary: the stored episode row carries media_type "serial" (the
//     module registry's vocabulary) and NO stored row carries "video" — the
//     literal the SPA gates presumed and no scanner writes,
//   - descriptor: GET /items/{id}/playback answers 200 with mode direct (the
//     unpacked branch of the direct|hls contract — nothing packs in this
//     test, and hls requires a published build), a packaging state, a
//     non-empty play_url carrying the fresh media token as its query
//     fallback, sections as a REAL array (the SPA reads .sections.length
//     unguarded — a wire null would crash the mount) projected from the
//     container chapters the scan stamped, and voiceovers as an array
//     carrying the episode's audio sidecar {index, label}, and the query
//     token alone opens the /media original (the cookieless fetch the player
//     executes).
//
// The expected values are re-derived independently of the other QA fixtures
// (different show/subfolder names) so a hard-coded value in shipped code
// cannot pass by coincidence.
package itest

import (
	"bytes"
	"encoding/json"
	"net/http"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/mellifera/mellifera/internal/stream"
)

// Fixture identity — one serial directory with one chapters-carrying episode
// and one voiceover audio sidecar in a Jpn/ language subfolder. Small by
// design: the assertion targets the descriptor CONTRACT, not library size.
const (
	vipDir    = "Video Item Pages Show S01 (QA)"
	vipEpBase = "Video Item Pages Show S01E01.mkv"
	vipEpRel  = vipDir + "/" + vipEpBase
	vipJpnRel = vipDir + "/Jpn/Video Item Pages Show S01E01.mka"

	// vipTokenQuery mirrors stream.tokenQuery (unexported; the drift warning
	// is the pbStreamsLane house pattern) — the cookie-primary delivery's
	// query-parameter fallback in play_url.
	vipTokenQuery = "?token="
)

// vipSidecar / vipDoc decode the scan-stamped document slices the assertions
// navigate (black box: api-local shapes are not imported).
type vipSidecar struct {
	RelativePath string `json:"relative_path"`
	Kind         string `json:"kind"`
	Language     string `json:"language"`
}

type vipDoc struct {
	Parsed struct {
		SeriesRelativePath string       `json:"series_relative_path"`
		Sidecars           []vipSidecar `json:"sidecars"`
	} `json:"parsed"`
}

// vipDescriptor keeps sections/voiceovers RAW: the wire ARRAY-ness is the
// contract the SPA player mounts, and a typed slice decode would silently
// accept a JSON null (Go decodes null into a nil slice without error).
type vipDescriptor struct {
	Mode       string          `json:"mode"`
	State      string          `json:"state"`
	PlayURL    string          `json:"play_url"`
	Sections   json.RawMessage `json:"sections"`
	Voiceovers json.RawMessage `json:"voiceovers"`
}

// vipArray decodes one descriptor array field, failing when the wire value is
// not a JSON array.
func vipArray(t *testing.T, raw json.RawMessage, field string) []map[string]any {
	t.Helper()
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 || trimmed[0] != '[' {
		t.Fatalf("%s = %s, want a JSON array (the player mounts the field unguarded)", field, raw)
	}
	var out []map[string]any
	if err := json.Unmarshal(trimmed, &out); err != nil {
		t.Fatalf("decode %s: %v (%s)", field, err, raw)
	}
	return out
}

// TestVideoItemPagesJointE2E is the video-item-pages acceptance floor: one
// fixture serial library through the real scan, then the stored-vocabulary and
// descriptor-shape joints over the real HTTP surface.
func TestVideoItemPagesJointE2E(t *testing.T) {
	w := pbNewWorld(t)

	// The hermetic fixture: one serial directory, one chapters-carrying
	// episode (pbMakeMKV stamps Intro 0-2s + Main 2-5s), one audio sidecar.
	libRoot := t.TempDir()
	dirAbs := filepath.Join(libRoot, vipDir)
	mustMkdir(t, dirAbs)
	pbMakeMKV(t, filepath.Join(dirAbs, vipEpBase), 5*time.Second, true)
	mustMkdir(t, filepath.Join(dirAbs, "Jpn"))
	mustWrite(t, filepath.Join(libRoot, vipJpnRel), []byte("jpn voiceover"))

	// The real scan: serial-scanner subprocess + real ffprobe. Exactly 2
	// discoveries (the serial record + the episode); the sidecar subfolder
	// leaks no items and warns about nothing.
	libID := pbCreateLibrary(t, w, "serial", libRoot, "QA Video Item Pages")
	res := pbScanLibrary(t, w, libID)
	if res.Discovered != 2 || res.Persisted != 2 {
		t.Fatalf("scan discovered=%d persisted=%d, want 2/2 (1 serial record + 1 episode; sidecars never items); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	if len(res.Warnings) != 0 {
		t.Fatalf("scan warnings = %v, want none (clean fixture)", res.Warnings)
	}
	items := pbItemByRel(t, w, libID)
	ep, ok := items[vipEpRel]
	if !ok {
		t.Fatalf("episode %q not persisted; have %v", vipEpRel, qaSerialMapKeys(items))
	}

	var doc vipDoc
	if err := json.Unmarshal(ep.Document, &doc); err != nil {
		t.Fatalf("decode episode document: %v", err)
	}
	sidecarIdx := -1
	for i, sc := range doc.Parsed.Sidecars {
		if sc.RelativePath == vipJpnRel {
			sidecarIdx = i
		}
	}

	t.Run("stored_episode_carries_the_serial_vocabulary", func(t *testing.T) {
		// The production vocabulary: the scanner stamps the module's type —
		// "serial" == the never-"video" guarantee the SPA bug violated (no
		// scanner writes the "video" literal anywhere).
		if ep.MediaType != "serial" {
			t.Errorf("media_type = %q, want serial", ep.MediaType)
		}
		for rel, it := range items {
			if it.MediaType == "video" {
				t.Errorf("%q: media_type = %q — no scanner writes the video literal (the SPA-gate fiction)", rel, it.MediaType)
			}
		}
		// The stored document IS a serial-scanner document (the joint: the
		// subprocess stamped it, the store kept it, the descriptor reads it).
		if doc.Parsed.SeriesRelativePath != vipDir {
			t.Errorf("parsed.series_relative_path = %q, want %q", doc.Parsed.SeriesRelativePath, vipDir)
		}
		if sidecarIdx < 0 {
			t.Fatalf("audio sidecar %q not stamped into the episode document: %+v", vipJpnRel, doc.Parsed.Sidecars)
		}
		if sc := doc.Parsed.Sidecars[sidecarIdx]; sc.Kind != "audio" || sc.Language != "Jpn" {
			t.Errorf("sidecar %d = %+v, want the Jpn audio fact", sidecarIdx, sc)
		}
	})

	t.Run("descriptor_matches_the_spa_mount_shape", func(t *testing.T) {
		status, body, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+"/api/v1/items/"+ep.ID+"/playback", w.token, nil)
		if status != http.StatusOK {
			t.Fatalf("descriptor: status %d, want 200 (body=%s)", status, body)
		}
		var d vipDescriptor
		if err := json.Unmarshal(body, &d); err != nil {
			t.Fatalf("decode descriptor: %v (body=%s)", err, body)
		}

		// The unpacked branch of the direct|hls contract: nothing packed in
		// this test, so the unconditional direct floor stands (hls requires
		// a published build). The fixture is a packable MKV (matroska facts),
		// so the descriptor honesty projection (tv-playback-unblock D1)
		// answers the descriptor-only preparing state — read-side, the
		// persisted namespace still sits at none.
		if d.Mode != stream.ModeDirect || d.State != stream.StatePreparing {
			t.Fatalf("descriptor = mode %q state %q, want direct/preparing (nothing packed; hls needs a published build; a packable MKV floor answers preparing)", d.Mode, d.State)
		}

		// The token-carrying play_url: the /media floor with the fresh media
		// token as the non-empty query fallback.
		q := strings.Index(d.PlayURL, vipTokenQuery)
		if !strings.HasPrefix(d.PlayURL, "/media/") || q < 0 || d.PlayURL[q+len(vipTokenQuery):] == "" {
			t.Fatalf("play_url = %q, want the /media floor carrying a non-empty token query", d.PlayURL)
		}

		// sections: a REAL array (Player.tsx reads .sections.length
		// unguarded) projecting the scan-stamped container chapters — both
		// fixture chapters, kind chapter, ordered by start, titles carried.
		sections := vipArray(t, d.Sections, "sections")
		if len(sections) != 2 {
			t.Fatalf("sections = %s, want the fixture's two container chapters", d.Sections)
		}
		for i, want := range []struct {
			start float64
			title string
		}{{0, "Intro"}, {2, "Main"}} {
			got := sections[i]
			kind, _ := got["kind"].(string)
			start, _ := got["start"].(float64)
			title, _ := got["title"].(string)
			if kind != stream.SectionKindChapter || start != want.start || title != want.title {
				t.Errorf("sections[%d] = %v, want kind %q start %v title %q", i, got, stream.SectionKindChapter, want.start, want.title)
			}
		}

		// voiceovers: an array carrying the episode's audio sidecar as
		// {index, label} — the index is the sidecar's DOCUMENT index (the
		// same n= space the sidecar media variant resolves), the label the
		// stamped language.
		voiceovers := vipArray(t, d.Voiceovers, "voiceovers")
		if len(voiceovers) != 1 {
			t.Fatalf("voiceovers = %s, want exactly the Jpn audio sidecar", d.Voiceovers)
		}
		idx, _ := voiceovers[0]["index"].(float64)
		label, _ := voiceovers[0]["label"].(string)
		if int(idx) != sidecarIdx || label != "Jpn" {
			t.Errorf("voiceovers[0] = %v, want {index:%d label:Jpn}", voiceovers[0], sidecarIdx)
		}

		// The query token ALONE opens the original — the cookieless fetch the
		// player executes (no bearer, no cookie: the client keeps no jar).
		mStatus, mBody, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+d.PlayURL, "", nil)
		if mStatus != http.StatusOK {
			t.Fatalf("media via play_url token: status %d, want 200 (body=%s)", mStatus, mBody)
		}
	})
}
